(7161186, 1098957, 65234, '<td valign="top">I love blue-eyed kitties :-) The matching jeweled collar is a nice touch.</td>', 'I love blue-eyed kitties :-) The matching jeweled collar is a nice touch.', '2014-01-22 15:39:23.000000', NULL, 1),
(7161187, 1098821, 65234, '<td valign="top">Not the sort of flower arrangement I expect ... but I like it.  It''s exuberant, maybe a bit extravagant.  Makes me stop and look a bit longer.</td>', 'Not the sort of flower arrangement I expect ... but I like it.  It''s exuberant, maybe a bit extravagant.  Makes me stop and look a bit longer.', '2014-01-22 15:41:01.000000', NULL, 1),
